    cpu_percent: float
    #: Memory it holds, in bytes: its resident memory on its host.
    memory_bytes: int
    #: How many measures it is made of: two reads for the reading now; for a step, the minutes the host measured it in.
    samples: int
    #: The same as a number of cores.
    cpu_cores: Optional[float] = None
    #: Its busiest minute, as a percent of all its vCPUs.
    cpu_peak_percent: Optional[float] = None
    #: Percent of the last 10 seconds some task of it waited for a CPU.
    cpu_wait_percent: Optional[float] = None
    #: Percent of the last 10 seconds some task of it waited for memory.
    memory_stall_percent: Optional[float] = None
    #: The most memory it has held, in bytes; for a step, its highest minute's average.
    memory_peak_bytes: Optional[int] = None
    #: Bytes its disks read a second.
    disk_read_bytes_per_second: Optional[float] = None
    #: Bytes its disks wrote a second.
    disk_write_bytes_per_second: Optional[float] = None
    #: Reads its disks completed a second.
    disk_read_ops_per_second: Optional[float] = None
    #: Writes its disks completed a second.
    disk_write_ops_per_second: Optional[float] = None

    @classmethod
    def from_dict(cls, d: Dict[str, Any]) -> "MetricPoint":
        return cls(
            at=d["at"],
            cpu_percent=d["cpuPercent"],
            memory_bytes=d["memoryBytes"],
            samples=d["samples"],
            cpu_cores=d.get("cpuCores"),
            cpu_peak_percent=d.get("cpuPeakPercent"),
            cpu_wait_percent=d.get("cpuWaitPercent"),
            memory_stall_percent=d.get("memoryStallPercent"),
            memory_peak_bytes=d.get("memoryPeakBytes"),
            disk_read_bytes_per_second=d.get("diskReadBytesPerSecond"),
            disk_write_bytes_per_second=d.get("diskWriteBytesPerSecond"),
            disk_read_ops_per_second=d.get("diskReadOpsPerSecond"),
            disk_write_ops_per_second=d.get("diskWriteOpsPerSecond"),
        )

    def to_dict(self) -> Dict[str, Any]:
        return compact({
            "at": self.at,
            "cpuPercent": self.cpu_percent,
            "memoryBytes": self.memory_bytes,
            "samples": self.samples,
            "cpuCores": self.cpu_cores,
            "cpuPeakPercent": self.cpu_peak_percent,
            "cpuWaitPercent": self.cpu_wait_percent,
            "memoryStallPercent": self.memory_stall_percent,
            "memoryPeakBytes": self.memory_peak_bytes,
            "diskReadBytesPerSecond": self.disk_read_bytes_per_second,
            "diskWriteBytesPerSecond": self.disk_write_bytes_per_second,
            "diskReadOpsPerSecond": self.disk_read_ops_per_second,
            "diskWriteOpsPerSecond": self.disk_write_ops_per_second,
        })


