@dataclass
class MachineUpdate:
    """A change to a machine's settings: each field left out stays as it is."""

    #: Its name, unique in its project.
    name: Optional[str] = None
    #: Its labels, in place of its own; those under `runtime.` are kept.
    labels: Optional[Dict[str, str]] = None
    #: Seconds with nothing happening before it pauses, 60 to 86400; 0 never.
    idle_pause_seconds: Optional[int] = None
    #: Its vCPUs, grown while it runs; a running sandbox's vCPUs only grow. At least 1.
    vcpu: Optional[int] = None
    #: Its memory in GB (1 GB is 1,024 MiB), grown while it runs; a running sandbox's memory only grows. At least 1.
    memory_gb: Optional[float] = None
    #: Its disk in GB (1 GB is 1,024 MiB), grown while it runs, its file system with it; a disk only grows. At least 1.
    disk_gb: Optional[float] = None
    #: Who its commands run as from now when a call names no `user`: `runtime` or `root`. Running ones keep theirs.
    user: Optional[Literal["runtime", "root", "unknown"]] = None
    #: Environment variables to set, each over its own value, the others kept: the update answers once a running one holds the change (a paused one is given it at its wake), so each process, command and terminal it starts after the answer has them; processes already running keep the environment they started with. At most 32 variables and 32768 bytes of names and values in all, as a create's; values are never answered.
    env: Optional[Dict[str, str]] = None
    #: Names of environment variables to take out, the same way: gone from the next process it starts; processes already running keep them.
    remove_env: Optional[List[str]] = None
    #: The most it may cost in all, in US dollars (`"5.00"`), in place of its own: one paused at its old maxCost wakes at its next call under a higher one.
    max_cost: Optional[str] = None

    @classmethod
    def from_dict(cls, d: Dict[str, Any]) -> "MachineUpdate":
        return cls(
            name=d.get("name"),
            labels=d.get("labels"),
            idle_pause_seconds=d.get("idlePauseSeconds"),
            vcpu=d.get("vcpu"),
            memory_gb=d.get("memoryGB"),
            disk_gb=d.get("diskGB"),
            user=open_enum(d["user"], ("runtime", "root",)) if d.get("user") is not None else None,
            env=d.get("env"),
            remove_env=d["removeEnv"] if d.get("removeEnv") is not None else None,
            max_cost=d.get("maxCost"),
        )

    def to_dict(self) -> Dict[str, Any]:
        return compact({
            "name": self.name,
            "labels": self.labels,
            "idlePauseSeconds": self.idle_pause_seconds,
            "vcpu": self.vcpu,
            "memoryGB": self.memory_gb,
            "diskGB": self.disk_gb,
            "user": self.user,
            "env": self.env,
            "removeEnv": self.remove_env,
            "maxCost": self.max_cost,
        })


